import React from "react";
import { Carousel } from "react-responsive-carousel";
import { Box, Typography } from "@mui/material";
import "react-responsive-carousel/lib/styles/carousel.min.css";
import "../styling/carousel.css"; 

const TestimonialsCarousel = () => {
  const testimonials = [
    { text: "Seamless consultation experience!", author: "John Doe" },
    {
      text: "Fast delivery of medicines. Highly recommend!",
      author: "Jane Smith",
    },
    {
      text: "Friendly doctors and efficient appointments!",
      author: "David Lee",
    },
  ];

  return (
    <div>
      <h1 style={{ display: "flex", justifyContent: "center" }}>
        What Our Pateints Say
      </h1>
      <div className="carousel-container">
        <Carousel
          showArrows={true}
          infiniteLoop={true}
          showThumbs={false}
          showStatus={false}
          autoPlay={true}
          interval={4000}
        >
          {testimonials.map((testimonial, index) => (
            <Box key={index} className="testimonial-box" textAlign="center">
              <img
                style={{
                  height: "150px",
                  width: "150px",
                  borderRadius: "50%",
                }}
                src="data:image/jpeg;base64,"
              />
              <Typography
                className="testimonial-text"
                variant="body1"
                paragraph
              >
                "{testimonial.text}"
              </Typography>
              <Typography className="testimonial-author" variant="h6">
                - {testimonial.author}
              </Typography>
            </Box>
          ))}
        </Carousel>
      </div>
    </div>
  );
};

export default TestimonialsCarousel;
